// Get all unique station IDs served by a line
export function getLineStations(lineId: string): string[] {
  const routes = LINE_ROUTES[lineId];
  if (!routes) return [];
  const seen = new Set<string>();
  for (const dir of ['inbound', 'outbound'] as const) {
    for (const route of routes[dir]) {
      for (const nid of route.naptanIds) {
        seen.add(nid);
      }
    }
  }
  return Array.from(seen);
}

// Get station display name from NaPTAN ID
export function getStationName(naptanId: string): string | undefined {
  return LINE_STATIONS[naptanId]?.name;
}
